// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testFuzz_property(address caddress, address[] memory _tos, uint[] memory v, address sender) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.assume(caddress != address(c));
        vm.assume(sender != address(0));
        bytes4 id=bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool[] memory correctTargetReached = new bool[]( _tos.length);
        targetRecorder rec = new targetRecorder();
        address recorderAddr = address(rec);
        for (uint i=0;i<_tos.length;i++){
            correctTargetReached[i] = false;
        }
        vm.prank(sender);
        c.transfer(sender, recorderAddr, _tos, v);
        uint256 callsReceived = rec.numCalls();
        assertTrue(callsReceived == _tos.length, "call count mismatch");
        for (uint i=0;i<callsReceived;i++){
            assertTrue(rec.recordedTarget(i) == _tos[i], "incorrect target recorded");
        }
    }
}

contract targetRecorder {
    address[] public recordedTarget;
    uint256 public numCalls;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        recordedTarget.push(to);
        numCalls++;
        return true;
    }
}
